import { Controller, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '자원 담당자';
const USE_VALUES = ['사용', '미사용'];
const SCOPE_VALUES = ['전체', '부서', '개인'];

function present(v: unknown): boolean {
  return v !== undefined && v !== null && v !== '';
}

function intOf(v: unknown, label: string, min: number): number {
  const n = typeof v === 'number' ? v : Number(v);
  if (!Number.isInteger(n) || n < min) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

function optInt(v: unknown, label: string, min: number): number | null {
  if (!present(v)) {
    return null;
  }
  return intOf(v, label, min);
}

function requiredText(v: unknown, label: string): string {
  if (typeof v !== 'string' || v.trim() === '') {
    throw new ApiError(422, 'REQUIRED_VALUE_MISSING', label + '은(는) 필수입니다.');
  }
  if (v.trim().length > 200) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 200자 이내로 입력하세요.');
  }
  return v.trim();
}

function optionOf(v: unknown, allowed: string[], label: string): string | null {
  if (!present(v)) {
    return null;
  }
  if (typeof v !== 'string' || !allowed.includes(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr03303Controller {
  @Post('/resource-categories')
  @HttpCode(200)
  async createResourceCategory(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const name = requiredText(data['name'], '자원 분류명');
    const parentId = optInt(data['parentCategoryId'], '상위 자원 분류', 1);
    const sortOrder = optInt(data['sortOrder'], '정렬 순서', 0);
    const useYn = optionOf(data['useYn'], USE_VALUES, '사용 여부') ?? '사용';
    return transaction(async (db) => {
      if (parentId !== null) {
        const parents = await db.query(
          `SELECT resource_category_id FROM resource_category WHERE resource_category_id = CAST(:parentId AS bigint)`,
          { parentId },
        );
        if (parents.length === 0) {
          throw new ApiError(404, 'RESOURCE_CATEGORY_NOT_FOUND', '상위 자원 분류를 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO resource_category (name, parent_category_id, sort_order, use_yn, created_at, updated_at)
         VALUES (:name, CAST(:parentId AS bigint), CAST(:sortOrder AS integer), :useYn, now(), now())
         RETURNING resource_category_id AS "resourceCategoryId", name AS "name"`,
        { name, parentId, sortOrder, useYn },
      );
      return rows[0];
    });
  }

  @Patch('/resource-categories/:resourceCategoryId')
  async updateResourceCategory(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['resourceCategoryId'], '자원 분류 ID', 1);
    const data = checks.inputOf(req.body);
    const name = present(data['name']) ? requiredText(data['name'], '자원 분류명') : null;
    const sortOrder = optInt(data['sortOrder'], '정렬 순서', 0);
    const useYn = optionOf(data['useYn'], USE_VALUES, '사용 여부');
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT resource_category_id FROM resource_category WHERE resource_category_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESOURCE_CATEGORY_NOT_FOUND', '자원 분류를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE resource_category
         SET name = COALESCE(CAST(:name AS varchar), name),
             sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order),
             use_yn = COALESCE(CAST(:useYn AS varchar), use_yn),
             updated_at = now()
         WHERE resource_category_id = CAST(:id AS bigint)
         RETURNING resource_category_id AS "resourceCategoryId", name AS "name"`,
        { id, name, sortOrder, useYn },
      );
      return rows[0];
    });
  }

  @Delete('/resource-categories/:resourceCategoryId')
  async deleteResourceCategory(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['resourceCategoryId'], '자원 분류 ID', 1);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT resource_category_id FROM resource_category WHERE resource_category_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESOURCE_CATEGORY_NOT_FOUND', '자원 분류를 찾을 수 없습니다.');
      }
      const used = await db.query(
        `SELECT resource_id FROM resource WHERE resource_category_id = CAST(:id AS bigint)`,
        { id },
      );
      if (used.length > 0) {
        throw new ApiError(409, 'RESOURCE_CATEGORY_HAS_RESOURCES', '하위 자원이 있는 분류는 삭제할 수 없습니다.');
      }
      const children = await db.query(
        `SELECT resource_category_id FROM resource_category WHERE parent_category_id = CAST(:id AS bigint)`,
        { id },
      );
      if (children.length > 0) {
        throw new ApiError(409, 'RESOURCE_CATEGORY_HAS_RESOURCES', '하위 분류가 있는 분류는 삭제할 수 없습니다.');
      }
      await db.execute(
        `DELETE FROM resource_category WHERE resource_category_id = CAST(:id AS bigint)`,
        { id },
      );
      return {};
    });
  }

  @Post('/resources')
  @HttpCode(200)
  async createResource(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (!present(data['resourceCategoryId'])) {
      throw new ApiError(422, 'REQUIRED_VALUE_MISSING', '자원 분류는 필수입니다.');
    }
    const categoryId = intOf(data['resourceCategoryId'], '자원 분류', 1);
    const name = requiredText(data['name'], '자원명');
    if (!present(data['visibilityScope'])) {
      throw new ApiError(422, 'REQUIRED_VALUE_MISSING', '공개범위는 필수입니다.');
    }
    if (!present(data['approvalRequired'])) {
      throw new ApiError(422, 'REQUIRED_VALUE_MISSING', '승인 절차 사용 여부는 필수입니다.');
    }
    const scope = optionOf(data['visibilityScope'], SCOPE_VALUES, '공개범위');
    const approval = optionOf(data['approvalRequired'], USE_VALUES, '승인 절차 사용 여부');
    const sortOrder = optInt(data['sortOrder'], '정렬 순서', 0);
    const managerId = optInt(data['managerId'], '담당자', 1);
    // 가정: 사용 여부를 보내지 않으면 '사용'으로 등록한다.
    const useStatus = optionOf(data['useStatus'], USE_VALUES, '사용 여부') ?? '사용';
    return transaction(async (db) => {
      const cats = await db.query(
        `SELECT resource_category_id FROM resource_category WHERE resource_category_id = CAST(:categoryId AS bigint)`,
        { categoryId },
      );
      if (cats.length === 0) {
        throw new ApiError(404, 'RESOURCE_CATEGORY_NOT_FOUND', '자원 분류를 찾을 수 없습니다.');
      }
      if (managerId !== null) {
        const emps = await db.query(
          `SELECT employee_id FROM employee WHERE employee_id = CAST(:managerId AS bigint)`,
          { managerId },
        );
        if (emps.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '담당자를 찾을 수 없습니다.');
        }
      }
      const dup = await db.query(
        `SELECT resource_id FROM resource WHERE resource_category_id = CAST(:categoryId AS bigint) AND name = :name`,
        { categoryId, name },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'RESOURCE_NAME_DUPLICATED', '같은 분류에 동일한 자원명이 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO resource (resource_category_id, manager_id, name, sort_order, visibility_scope, approval_required, use_status, created_at, updated_at)
         VALUES (CAST(:categoryId AS bigint), CAST(:managerId AS bigint), :name, CAST(:sortOrder AS integer), :scope, :approval, :useStatus, now(), now())
         RETURNING resource_id AS "resourceId", name AS "name"`,
        { categoryId, managerId, name, sortOrder, scope, approval, useStatus },
      );
      return rows[0];
    });
  }

  @Patch('/resources/:resourceId')
  async updateResource(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['resourceId'], '자원 ID', 1);
    const data = checks.inputOf(req.body);
    const newCategoryId = optInt(data['resourceCategoryId'], '자원 분류', 1);
    const newName = present(data['name']) ? requiredText(data['name'], '자원명') : null;
    const sortOrder = optInt(data['sortOrder'], '정렬 순서', 0);
    const managerId = optInt(data['managerId'], '담당자', 1);
    const useStatus = optionOf(data['useStatus'], USE_VALUES, '사용 여부');
    return transaction(async (db) => {
      const current = await db.query(
        `SELECT resource_category_id AS "categoryId", name AS "name" FROM resource WHERE resource_id = CAST(:id AS bigint)`,
        { id },
      );
      if (current.length === 0) {
        throw new ApiError(404, 'RESOURCE_NOT_FOUND', '자원을 찾을 수 없습니다.');
      }
      const categoryId = newCategoryId ?? Number(current[0]['categoryId']);
      const name = newName ?? String(current[0]['name']);
      if (newCategoryId !== null) {
        const cats = await db.query(
          `SELECT resource_category_id FROM resource_category WHERE resource_category_id = CAST(:categoryId AS bigint)`,
          { categoryId },
        );
        if (cats.length === 0) {
          throw new ApiError(404, 'RESOURCE_CATEGORY_NOT_FOUND', '자원 분류를 찾을 수 없습니다.');
        }
      }
      if (managerId !== null) {
        const emps = await db.query(
          `SELECT employee_id FROM employee WHERE employee_id = CAST(:managerId AS bigint)`,
          { managerId },
        );
        if (emps.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '담당자를 찾을 수 없습니다.');
        }
      }
      const dup = await db.query(
        `SELECT resource_id FROM resource
         WHERE resource_category_id = CAST(:categoryId AS bigint) AND name = :name AND resource_id <> CAST(:id AS bigint)`,
        { categoryId, name, id },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'RESOURCE_NAME_DUPLICATED', '같은 분류에 동일한 자원명이 있습니다.');
      }
      const rows = await db.query(
        `UPDATE resource
         SET resource_category_id = CAST(:categoryId AS bigint),
             name = :name,
             sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order),
             manager_id = COALESCE(CAST(:managerId AS bigint), manager_id),
             use_status = COALESCE(CAST(:useStatus AS varchar), use_status),
             updated_at = now()
         WHERE resource_id = CAST(:id AS bigint)
         RETURNING resource_id AS "resourceId", use_status AS "useStatus"`,
        { id, categoryId, name, sortOrder, managerId, useStatus },
      );
      return rows[0];
    });
  }

  @Delete('/resources/:resourceId')
  async deleteResource(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['resourceId'], '자원 ID', 1);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT resource_id FROM resource WHERE resource_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESOURCE_NOT_FOUND', '자원을 찾을 수 없습니다.');
      }
      // TODO(질문): 예약 테이블이 schema.sql에 없어 예약 내역 확인(409 RESOURCE_HAS_RESERVATIONS)을 하지 못했다.
      await db.execute(
        `DELETE FROM resource WHERE resource_id = CAST(:id AS bigint)`,
        { id },
      );
      return {};
    });
  }
}

