import { useState } from 'react';
import { Band, Badge, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, RefName, Select, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row, Column } from '../kit';

const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const SCOPE_OPTIONS: [string, string][] = [['전체', '전체'], ['부서', '부서'], ['개인', '개인']];

type DrawerState = { kind: 'catNew' | 'catEdit' | 'catDel' | 'resNew' | 'resEdit' | 'resDel'; row?: Row } | null;

function CategoryForm({ role, row, onSaved }: { role: string; row?: Row; onSaved: (r: Row) => void }) {
  const [name, setName] = useState(String(row?.name ?? ''));
  const [parent, setParent] = useState<unknown>(row?.parentCategoryId ?? '');
  const [sortOrder, setSortOrder] = useState<unknown>(row?.sortOrder ?? '');
  const [useYn, setUseYn] = useState(String(row?.useYn ?? '사용'));
  return (
    <Form
      submit={row ? '수정' : '등록'}
      onSubmit={async () => {
        if (!name.trim()) {
          throw new Error('자원 분류명을 입력하세요.');
        }
        const body: Row = { name, sortOrder, useYn };
        if (!row) {
          body.parentCategoryId = parent;
        }
        const saved = row
          ? await call('PATCH', '/resource-categories/' + row.resourceCategoryId, role, body)
          : await call('POST', '/resource-categories', role, body);
        onSaved({ ...row, ...body, ...saved });
      }}
    >
      <Field label="자원 분류명" required wide>
        <TextInput value={name} onChange={setName} />
      </Field>
      {!row && (
        <Field label="상위 자원 분류">
          <LookupSelect table="resource_category" role={role} value={parent} onChange={setParent} />
        </Field>
      )}
      <Field label="정렬 순서">
        <NumberInput value={sortOrder} onChange={setSortOrder} />
      </Field>
      <Field label="사용 여부">
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
      </Field>
    </Form>
  );
}

function ResourceForm({ role, row, onSaved }: { role: string; row?: Row; onSaved: (r: Row) => void }) {
  const [categoryId, setCategoryId] = useState<unknown>(row?.resourceCategoryId ?? '');
  const [name, setName] = useState(String(row?.name ?? ''));
  const [sortOrder, setSortOrder] = useState<unknown>(row?.sortOrder ?? '');
  const [managerId, setManagerId] = useState<unknown>(row?.managerId ?? '');
  const [useStatus, setUseStatus] = useState(String(row?.useStatus ?? '사용'));
  const [scope, setScope] = useState(String(row?.visibilityScope ?? '전체'));
  const [approval, setApproval] = useState(String(row?.approvalRequired ?? '미사용'));
  return (
    <Form
      submit={row ? '수정' : '등록'}
      onSubmit={async () => {
        if (categoryId === '' || categoryId === null) {
          throw new Error('자원 분류를 선택하세요.');
        }
        if (!name.trim()) {
          throw new Error('자원명을 입력하세요.');
        }
        const body: Row = { resourceCategoryId: categoryId, name, sortOrder, managerId, useStatus };
        if (!row) {
          body.visibilityScope = scope;
          body.approvalRequired = approval;
        }
        const saved = row
          ? await call('PATCH', '/resources/' + row.resourceId, role, body)
          : await call('POST', '/resources', role, body);
        onSaved({ ...row, ...body, ...saved });
      }}
    >
      <Field label="자원 분류" required>
        <LookupSelect table="resource_category" role={role} value={categoryId} onChange={setCategoryId} />
      </Field>
      <Field label="자원명" required>
        <TextInput value={name} onChange={setName} />
      </Field>
      <Field label="정렬 순서">
        <NumberInput value={sortOrder} onChange={setSortOrder} />
      </Field>
      <Field label="담당자">
        <LookupSelect table="employee" role={role} value={managerId} onChange={setManagerId} />
      </Field>
      <Field label="사용 여부">
        <Select value={useStatus} onChange={setUseStatus} options={USE_OPTIONS} />
      </Field>
      {!row && (
        <Field label="공개범위" required>
          <Select value={scope} onChange={setScope} options={SCOPE_OPTIONS} />
        </Field>
      )}
      {!row && (
        <Field label="승인 절차 사용 여부" required>
          <Select value={approval} onChange={setApproval} options={USE_OPTIONS} />
        </Field>
      )}
    </Form>
  );
}

export default function FnSfr03303Page({ role, notify }: PageProps) {
  const [cats, setCats] = useState<Row[]>([]);
  const [ress, setRess] = useState<Row[]>([]);
  const [drawer, setDrawer] = useState<DrawerState>(null);

  const upsert = (list: Row[], key: string, item: Row): Row[] => {
    const exists = list.some((r) => r[key] === item[key]);
    return exists ? list.map((r) => (r[key] === item[key] ? item : r)) : [item, ...list];
  };

  const catColumns: Column[] = [
    { key: 'resourceCategoryId', label: '자원 분류 ID' },
    { key: 'name', label: '자원 분류명' },
    { key: 'parentCategoryId', label: '상위 자원 분류', render: (r) => (r.parentCategoryId ? <RefName table="resource_category" role={role} value={r.parentCategoryId} /> : '-') },
    { key: 'sortOrder', label: '정렬 순서' },
    { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r.useYn} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r) => (
        <span>
          <button type="button" onClick={() => setDrawer({ kind: 'catEdit', row: r })}>수정</button>
          <button type="button" onClick={() => setDrawer({ kind: 'catDel', row: r })}>삭제</button>
        </span>
      ),
    },
  ];

  const resColumns: Column[] = [
    { key: 'resourceId', label: '자원 ID' },
    { key: 'name', label: '자원명' },
    { key: 'resourceCategoryId', label: '자원 분류', render: (r) => <RefName table="resource_category" role={role} value={r.resourceCategoryId} /> },
    { key: 'managerId', label: '담당자', render: (r) => (r.managerId ? <RefName table="employee" role={role} value={r.managerId} /> : '-') },
    { key: 'sortOrder', label: '정렬 순서' },
    { key: 'visibilityScope', label: '공개범위' },
    { key: 'approvalRequired', label: '승인 절차 사용 여부' },
    { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r) => (
        <span>
          <button type="button" onClick={() => setDrawer({ kind: 'resEdit', row: r })}>수정</button>
          <button type="button" onClick={() => setDrawer({ kind: 'resDel', row: r })}>삭제</button>
        </span>
      ),
    },
  ];

  const unused = ress.filter((r) => r.useStatus === '미사용').length;
  const close = () => setDrawer(null);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['등록·수정한 분류', cats.length], ['등록·수정한 자원', ress.length], ['미사용 자원', unused]]} />
      </section>

      <section className="box span-12">
        <h2>자원 분류</h2>
        <Band total={cats.length}>
          <button type="button" onClick={() => setDrawer({ kind: 'catNew' })}>분류 등록</button>
        </Band>
        <DataTable columns={catColumns} rows={cats} empty="이 화면에서 처리한 분류가 없습니다." />
      </section>

      <section className="box span-12">
        <h2>자원 목록</h2>
        <Band total={ress.length}>
          <button type="button" onClick={() => setDrawer({ kind: 'resNew' })}>자원 등록</button>
        </Band>
        <DataTable columns={resColumns} rows={ress} empty="이 화면에서 처리한 자원이 없습니다." />
      </section>

      {drawer && (drawer.kind === 'catNew' || drawer.kind === 'catEdit') && (
        <Drawer title={drawer.kind === 'catNew' ? '자원 분류 등록' : '자원 분류 수정'} onClose={close}>
          <CategoryForm
            role={role}
            row={drawer.row}
            onSaved={(r) => {
              setCats((list) => upsert(list, 'resourceCategoryId', r));
              notify(drawer.kind === 'catNew' ? '자원 분류를 등록했습니다.' : '자원 분류를 수정했습니다.');
              close();
            }}
          />
        </Drawer>
      )}

      {drawer && (drawer.kind === 'resNew' || drawer.kind === 'resEdit') && (
        <Drawer title={drawer.kind === 'resNew' ? '자원 등록' : '자원 수정'} onClose={close}>
          <ResourceForm
            role={role}
            row={drawer.row}
            onSaved={(r) => {
              setRess((list) => upsert(list, 'resourceId', r));
              notify(drawer.kind === 'resNew' ? '자원을 등록했습니다.' : '자원을 수정했습니다.');
              close();
            }}
          />
        </Drawer>
      )}

      {drawer && drawer.kind === 'catDel' && drawer.row && (
        <Drawer title="자원 분류 삭제" onClose={close}>
          <Form
            submit="삭제"
            danger
            note={'"' + String(drawer.row.name) + '" 분류를 삭제합니다. 하위 자원이 있으면 삭제할 수 없습니다.'}
            onSubmit={async () => {
              await call('DELETE', '/resource-categories/' + drawer.row?.resourceCategoryId, role);
              setCats((list) => list.filter((r) => r.resourceCategoryId !== drawer.row?.resourceCategoryId));
              notify('자원 분류를 삭제했습니다.');
              close();
            }}
          />
        </Drawer>
      )}

      {drawer && drawer.kind === 'resDel' && drawer.row && (
        <Drawer title="자원 삭제" onClose={close}>
          <Form
            submit="삭제"
            danger
            note={'"' + String(drawer.row.name) + '" 자원을 삭제합니다. 예약 내역이 있으면 삭제하지 말고 사용 여부를 미사용으로 수정하세요.'}
            onSubmit={async () => {
              await call('DELETE', '/resources/' + drawer.row?.resourceId, role);
              setRess((list) => list.filter((r) => r.resourceId !== drawer.row?.resourceId));
              notify('자원을 삭제했습니다.');
              close();
            }}
          />
        </Drawer>
      )}
    </div>
  );
}
